(() => {
  const queuedSuccessKey = 'tuby:success-toast';
  const maximumVisibleToasts = 4;

  window.tubyErrorMessage = (xhr, fallback = 'Tuby could not complete this action.') => {
    try {
      const message = JSON.parse(xhr?.responseText ?? '').error;
      if (typeof message === 'string' && message.trim() !== '') return message;
    } catch {
      // The fallback also covers HTML responses generated by a reverse proxy.
    }
    return fallback;
  };

  window.tubyFetchErrorMessage = async (response, fallback = 'Tuby could not complete this action.') => {
    try {
      const payload = await response.json();
      if (typeof payload.error === 'string' && payload.error.trim() !== '') return payload.error;
    } catch {
      // The fallback also covers empty and non-JSON responses.
    }
    return fallback;
  };

  window.tubyShowError = message => showToast(message, 'error', 7500);
  window.tubyShowSuccess = message => showToast(message, 'success', 7500);
  window.tubyQueueSuccess = message => {
    try {
      sessionStorage.setItem(queuedSuccessKey, message);
    } catch {
      // A blocked sessionStorage must not prevent the successful action.
    }
  };

  document.addEventListener('htmx:responseError', event => {
    if (hasLocalErrorSurface(event.detail.elt)) return;
    window.tubyShowError(window.tubyErrorMessage(event.detail.xhr));
  });

  document.addEventListener('htmx:sendError', event => {
    if (hasLocalErrorSurface(event.detail.elt)) return;
    window.tubyShowError('Tuby could not reach the server. Check your connection and try again.');
  });

  document.addEventListener('htmx:timeout', event => {
    if (hasLocalErrorSurface(event.detail.elt)) return;
    window.tubyShowError('The request timed out. Try again.');
  });

  document.addEventListener('htmx:afterRequest', event => {
    const failures = partialRefreshFailures(event.detail);
    if (failures > 0) {
      const suffix = failures === 1 ? '' : 's';
      window.tubyShowError(`${failures} channel${suffix} could not be refreshed. Try again later.`);
    }
  });

  const partialRefreshFailures = detail => {
    if (!detail.successful || !detail.elt?.matches?.('[data-refresh-channels]')) return 0;
    try {
      const payload = JSON.parse(detail.xhr.responseText);
      return Array.isArray(payload.failed) ? payload.failed.length : 0;
    } catch {
      return 0;
    }
  };

  const hasLocalErrorSurface = element => Boolean(element?.closest?.(
    '[data-add-channel], [data-channel-settings], [hx-confirm], .duration-button',
  ));

  const showToast = (message, kind, duration) => {
    const container = feedbackToasts();
    trimToastStack(container);
    const toast = document.createElement('div');
    toast.className = `feedback-toast is-${kind}`;
    toast.style.setProperty('--toast-duration', `${duration}ms`);
    toast.setAttribute('role', kind === 'error' ? 'alert' : 'status');
    toast.setAttribute('aria-live', kind === 'error' ? 'assertive' : 'polite');
    toast.innerHTML = '<span data-toast-message></span><button type="button">×</button>';
    toast.querySelector('[data-toast-message]').textContent = message;
    const dismiss = toast.querySelector('button');
    dismiss.setAttribute('aria-label', `Dismiss ${kind} message`);
    dismiss.addEventListener('click', () => removeToast(toast));
    container.append(toast);
    toast.hideTimer = setTimeout(() => removeToast(toast), duration);
  };

  const feedbackToasts = () => {
    const existing = document.querySelector('#feedback-toasts');
    if (existing) return existing;
    const container = document.createElement('div');
    container.id = 'feedback-toasts';
    container.className = 'feedback-toasts';
    container.setAttribute('aria-label', 'Notifications');
    document.body.append(container);
    return container;
  };

  const trimToastStack = container => {
    while (container.childElementCount >= maximumVisibleToasts) {
      removeToast(container.firstElementChild);
    }
  };

  const removeToast = toast => {
    if (!toast) return;
    clearTimeout(toast.hideTimer);
    const container = toast.parentElement;
    toast.remove();
    if (container?.childElementCount === 0) container.remove();
  };

  const showQueuedSuccess = () => {
    try {
      const message = sessionStorage.getItem(queuedSuccessKey);
      if (!message) return;
      sessionStorage.removeItem(queuedSuccessKey);
      window.tubyShowSuccess(message);
    } catch {
      // There is no queued feedback when sessionStorage is unavailable.
    }
  };

  showQueuedSuccess();
})();
